public class DateTimeZone_forID_TriageGen2Test {











    @Test
    public void testForID_PositiveOffsetNonZero() {
        // Testing fixedOffsetZone branch for positive offset
        // +05:00 = 5 * 3600 = 18000 seconds = 18000000 ms
        DateTimeZone result = DateTimeZone.forID("+05:00");
        Assert.assertNotNull(result);
        Assert.assertTrue("Should be a fixed offset zone", result.isFixed());
        // Note: printOffset might format differently, but we check if it works
        Assert.assertEquals(5 * 3600 * 1000, result.getOffset(0));
    }






}

